HF = PatternFill("solid", fgColor="1E2230")
BLUE = Font(name=AR, color="0000FF")
BLK = Font(name=AR)
GRN = Font(name=AR, color="008000")
YEL = PatternFill("solid", fgColor="FFFF00")
WR = Alignment(wrap_text=True, vertical="top")

def header(ws, cols, widths=None):
    for i, c in enumerate(cols, 1):
        x = ws.cell(1, i, c); x.font = H; x.fill = HF; x.alignment = WR
    ws.freeze_panes = "B2"
    for i, w in enumerate(widths or [], 1):
        ws.column_dimensions[L(i)].width = w

def put(ws, r, c, v, font=BLK):
    x = ws.cell(r, c, v); x.font = font; x.alignment = WR
    return x

