EL = f"Руны!$A$2:$A${EL_N}"
def el(col, key): return f"INDEX(Руны!${col}$2:${col}${EL_N},MATCH({key},{EL},0))"
def vb(col, key): return f"INDEX(Руны!${col}$14:${col}$23,MATCH({key},Руны!$A$14:$A$23,0))"
def tg(col, key): return f"INDEX(Руны!${col}$27:${col}$30,MATCH({key},Руны!$A$27:$A$30,0))"
def prompt(tagc, verbc, elc):
    return ('="Flat game UI rune icon, 256x256, centered on a dark slate (#1E2230) square tile. An outer "&'
            + tg("C", tagc) + '&", thick carved "&' + el("F", elc) + '&" stroke"&' + el("G", elc)
            + '&" and a "&' + el("I", elc) + '&" around its outside. Inside: "&' + vb("C", verbc)
            + '&". Chiseled straight line ends, flat vector, no perspective, faint outer glow."')

