        put(P, r, 27, f"={c['Ярь']}{r}*(1-" + rk(5).format(r=R_) + ")").number_format = "0.0"
        put(P, r, 28, f"=IF({c['Ярь с рангом']}{r}>0,{c['Урон с рангом']}{r}/{c['Ярь с рангом']}{r},0)").number_format = "0.00"
