# ---------- list sheets (like PoE lists) ----------
def list_sheet(ws, names, extra_note):
    cols = ["Название", "Ранг", "Теги", "Биом", "Ярь", "Урон/с по откату", "Описание"]
    header(ws, cols, [24, 7, 40, 11, 7, 12, 60])
    for i, nm in enumerate(names, 2):
        put(ws, i, 1, nm)
        for j, pcol in enumerate(["Ранг", "Теги", "Биом", "Ярь с рангом", "Урон/с по откату", "Описание"], 2):
            x = put(ws, i, j, f"=INDEX(Параметры!${c[pcol]}$2:${c[pcol]}${P_LAST},MATCH($A{i},Параметры!$A$2:$A${P_LAST},0))", GRN)
            if j == 6: x.number_format = "0.0"
    put(ws, len(names) + 3, 1, extra_note, Font(name=AR, italic=True))

all_act = [x for rows in A.values() for x in rows]
